// Filtrar clientes que precisam de follow-up
// Ajustar para o fuso horário brasileiro (GMT-3)
const agora = new Date();

// Função para ajustar timestamp para fuso horário brasileiro
function ajustarParaFusoBrasil(data) {
  // Criar uma string de data no formato ISO com o fuso horário de São Paulo
  const dataString = data.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' });
  // Converter de volta para objeto Date
  return new Date(dataString);
}

// Ajustar a data atual para o fuso horário brasileiro
const agoraBrasil = ajustarParaFusoBrasil(agora);
console.log('Data atual (fuso BR):', agoraBrasil);

const clientesParaFollowUp = [];

// Obter todas as últimas mensagens
const ultimasMensagens = $node["Buscar Ultima Mensagem"].json;

for (const item of $input.all()) {
  const cliente = item.json;

  // Encontrar a última mensagem deste cliente
  const ultimaMensagem = ultimasMensagens.find(m => m.cliente_final_id === cliente.id);

  // Verificar se tem última mensagem
  if (!ultimaMensagem || !ultimaMensagem.timestamp) continue;

  // Converter para data e ajustar para fuso horário brasileiro
  const dataUltimaMensagem = new Date(ultimaMensagem.timestamp);
  const dataUltimaMensagemBR = ajustarParaFusoBrasil(dataUltimaMensagem);

  console.log(`Cliente ${cliente.id} - Última mensagem:`, dataUltimaMensagemBR);

  // Calcular diferença em dias (usando datas no mesmo fuso)
  const diffTime = Math.abs(agoraBrasil - dataUltimaMensagemBR);
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  console.log(`Cliente ${cliente.id} - Dias desde última mensagem:`, diffDays);

  // Adicionar tipo de follow-up baseado no tempo
  if (diffDays === 1) {
    clientesParaFollowUp.push({
      ...cliente,
      tipoFollowUp: 'lembrete_leve',
      diasEspera: diffDays,
      ultimaMensagemData: ultimaMensagem.timestamp
    });
  } else if (diffDays === 3) {
    clientesParaFollowUp.push({
      ...cliente,
      tipoFollowUp: 'reforcar_beneficio',
      diasEspera: diffDays,
      ultimaMensagemData: ultimaMensagem.timestamp
    });
  } else if (diffDays === 7) {
    clientesParaFollowUp.push({
      ...cliente,
      tipoFollowUp: 'encerramento',
      diasEspera: diffDays,
      ultimaMensagemData: ultimaMensagem.timestamp
    });
  }
}

// Retornar apenas clientes que precisam de follow-up
return clientesParaFollowUp.map(cliente => ({ json: cliente }));

// Depurar a saída do OpenAI
const openAIOutput = $input.first().json;
console.log('Saída do OpenAI:', JSON.stringify(openAIOutput, null, 2));

// Tentar extrair a mensagem de diferentes formatos possíveis
let mensagem = '';
if (typeof openAIOutput === 'string') {
  mensagem = openAIOutput;
} else if (openAIOutput.text) {
  mensagem = openAIOutput.text;
} else if (openAIOutput.content) {
  mensagem = openAIOutput.content;
} else if (openAIOutput.choices && openAIOutput.choices[0]) {
  mensagem = openAIOutput.choices[0].message?.content || '';
}

console.log('Mensagem extraída:', mensagem);

// Garantir que temos uma mensagem padrão se nada for encontrado
if (!mensagem) {
  if ($node["Loop Clientes"].json.tipoFollowUp === 'lembrete_leve') {
    mensagem = `Olá ${$node["Loop Clientes"].json.nome}! Só passando para saber se você chegou a ver as informações que te enviei. Estou à disposição para qualquer dúvida! 😊`;
  } else if ($node["Loop Clientes"].json.tipoFollowUp === 'reforcar_beneficio') {
    mensagem = `Oi ${$node["Loop Clientes"].json.nome}! Lembra que conversamos sobre nossos planos? Eles oferecem o melhor custo-benefício do mercado. Posso te ajudar com alguma dúvida específica?`;
  } else {
    mensagem = `Olá ${$node["Loop Clientes"].json.nome}, estou encerrando seu atendimento por aqui, mas fique à vontade para me chamar quando precisar! Estamos sempre à disposição. 🙌`;
  }
}

return [{
  json: {
    mensagemGerada: mensagem
  }
}];

// Obter o número do Twilio para envio
// Normalmente seria armazenado em uma configuração ou obtido de algum lugar

return [{
  json: {
    numeroRemetente: "+14155238886", // Substitua pelo número do Twilio real
    mensagemParaEnviar: $node["Debug OpenAI"].json.mensagemGerada
  }
}];
